import { phpDigitsToVersion } from './cwpConf';

// ─────────────────────────────────────────────────────────────────────────────
// Apache vhost files generated by CWP (/usr/local/apache/conf.d/vhosts/<fqdn>
// [.ssl].conf, docs/cwp/vhost-apache-sample.anon.conf): <VirtualHost> blocks
// with ServerName / ServerAlias / DocumentRoot, the PHP-FPM handler
// `SetHandler "proxy:unix:/opt/alt/php-fpmXX/usr/var/sockets/<user>.sock|fcgi://localhost"`,
// suPHP_UserGroup and the root ProxyPass. Line-based: `#` comments, `\`
// continuations, quoted arguments.
// ─────────────────────────────────────────────────────────────────────────────

export interface ApacheVhost {
  address: string | null;
  port: number | null;
  serverName: string | null;
  aliases: string[];
  documentRoot: string | null;
  /** '5.6'… from the FPM SetHandler. */
  fpmVersion: string | null;
  suphpUser: string | null;
  /** ProxyPass / <target> (CWP service sub-vhosts). */
  proxyPass: string | null;
  ssl: boolean;
}

/** Splits one Apache directive line into words (double / single quotes, backslash escapes inside quotes). */
export function apacheWords(line: string): string[] {
  const out: string[] = [];
  let i = 0;
  while (i < line.length) {
    while (i < line.length && /\s/.test(line[i])) i += 1;
    if (i >= line.length) break;
    const c = line[i];
    let w = '';
    if (c === '"' || c === "'") {
      i += 1;
      while (i < line.length && line[i] !== c) {
        if (line[i] === '\\' && i + 1 < line.length) { w += line[i + 1]; i += 2; continue; }
        w += line[i];
        i += 1;
      }
      i += 1;
    } else {
      while (i < line.length && !/\s/.test(line[i])) { w += line[i]; i += 1; }
    }
    out.push(w);
  }
  return out;
}

function logicalLines(text: string): string[] {
  const raw = text.replace(/\r\n?/g, '\n').split('\n');
  const out: string[] = [];
  let acc = '';
  for (const l of raw) {
    if (l.endsWith('\\')) { acc += `${l.slice(0, -1)} `; continue; }
    out.push(acc + l);
    acc = '';
  }
  if (acc) out.push(acc);
  return out;
}

const FPM_HANDLER = /proxy:unix:\/opt\/alt\/php-fpm(\d{2,3})\//i;

export function parseApacheVhosts(text: string): ApacheVhost[] {
  const out: ApacheVhost[] = [];
  let cur: ApacheVhost | null = null;
  for (const raw of logicalLines(text)) {
    // A `#` starts a comment only at the beginning of a line in Apache, but CWP glues `#####SSL` after a closing tag.
    const line = raw.replace(/^(\s*<\/VirtualHost>)\s*#.*$/i, '$1').trim();
    if (line === '' || line.startsWith('#')) continue;
    const open = /^<VirtualHost\s+([^>]*)>/i.exec(line);
    if (open) {
      const first = apacheWords(open[1])[0] ?? '';
      let address: string | null = null;
      let port: number | null = null;
      const v6 = /^\[([^\]]+)\](?::(\d+))?$/.exec(first);
      if (v6) { address = v6[1]; port = v6[2] ? Number(v6[2]) : null; }
      else {
        const i = first.lastIndexOf(':');
        if (i > 0) { address = first.slice(0, i); port = Number(first.slice(i + 1)) || null; }
        else address = first || null;
      }
      cur = { address, port, serverName: null, aliases: [], documentRoot: null, fpmVersion: null, suphpUser: null, proxyPass: null, ssl: port === 443 || port === 8443 };
      continue;
    }
    if (/^<\/VirtualHost>/i.test(line)) {
      if (cur) out.push(cur);
      cur = null;
      continue;
    }
    if (!cur) continue;
    const w = apacheWords(line);
    const name = (w[0] ?? '').toLowerCase();
    if (name === 'servername' && w[1]) cur.serverName = w[1].toLowerCase().replace(/:\d+$/, '').replace(/\.$/, '');
    else if (name === 'serveralias') cur.aliases.push(...w.slice(1).map((a) => a.toLowerCase().replace(/\.$/, '')).filter(Boolean));
    else if (name === 'documentroot' && w[1]) cur.documentRoot = w[1].replace(/\/+$/, '') || '/';
    else if (name === 'sethandler' && w[1]) {
      const m = FPM_HANDLER.exec(w[1]);
      if (m && !cur.fpmVersion) cur.fpmVersion = phpDigitsToVersion(m[1]);
    } else if (name === 'suphp_usergroup' && w[1]) cur.suphpUser = w[1];
    else if (name === 'proxypass' && w[1] === '/' && w[2]) cur.proxyPass = w[2];
    else if (name === 'sslengine' && (w[1] ?? '').toLowerCase() === 'on') cur.ssl = true;
  }
  if (cur) out.push(cur);
  return out;
}
